import {DesignRejection,approachIssues,physicalIssues,cellText} from './import-feedback.js';
import * as T from '../vendor/three.module.js';
import {createBattleNavigation} from './battle-navigation.js';
import {flightWorld} from './flight.js';
import {wavePlan,starterLayout,parseDesign,MAX_ENEMIES} from '../wave-rules.js';
import {siegeRoutes} from './siege-routes.js';
import {inspectCastle} from './castle-navigation.js';
import {inspectCastleFootprint} from './castle-footprint.js';
export function createWaves({world,scene,builder,physics,actor,follow,paused,onChanged=()=>{}}){
 const panel=document.createElement('section');panel.id='wave-panel';panel.innerHTML='<b>CRUSADERS · SHADOW SIEGE</b><p id="wave-status" role="status"></p><button id="wave-start">Quick starter / restart</button><button id="wave-saved">Defend current castle</button><button id="wave-next">Send next wave</button><button id="wave-repair">Repair 150 HP · 20 scrap</button><button id="wave-export">Export current castle</button><label>Import copied design <input id="wave-import" type="file" accept=".json"></label><small>WASD move · hold J to strike within 26 m · Pause freezes siege. Edit between waves, Apply, then defend current castle. Main core ends the run.</small>';document.body.append(panel);
 const css=document.createElement('style');css.textContent='#wave-panel{position:fixed;right:12px;top:75px;width:300px;max-height:55vh;overflow:auto;padding:14px;background:#142832ed;border:1px solid #8edace;z-index:15;font:14px system-ui;color:#eef4df}#wave-panel button{margin:3px;padding:7px;font-size:12px}#wave-import-feedback{white-space:pre-line;margin-top:10px;line-height:1.5;color:#ffd9b2}#wave-panel small{display:block;line-height:1.5}body:has(#castle-builder:not([hidden])) #wave-panel{display:none}';document.head.append(css);
 const $=id=>document.getElementById(id),nav=createBattleNavigation(world),root=new T.Group();scene.add(root);
 const pool=Array.from({length:MAX_ENEMIES},()=>{const sprite=actor.clone();sprite.material=actor.material.clone();sprite.material.color.set(0x39204f);sprite.scale.multiplyScalar(1.7);sprite.visible=false;root.add(sprite);return {sprite,active:false};});
 const state={phase:'ready',wave:0,hp:600,scrap:40,seed:1404,time:0,kills:0,routes:[],diagnostics:[],frameMs:[],spawned:0},held=new Set();let routes=[],cooldown=0,clock=0,layout=null,options={level:10,material:'fortress'},preparing=false,importing=false;
 const labels=['NORTH','EAST','SOUTH','WEST'];
 const importFeedback=document.createElement('div');importFeedback.id='wave-import-feedback';importFeedback.setAttribute?.('role','status');panel.append?.(importFeedback);
 function rejection(error){const issues=error.issues||[{code:'definition',message:error.message,suggestion:'Correct the copied file and retry. The applied castle is unchanged.'}];state.importReport={accepted:false,stage:error.stage||'definition',issues};importFeedback.textContent='IMPORT REJECTED — applied castle kept. '+issues.map(i=>[i.message,cellText(i.cell),i.suggestion].filter(Boolean).join(' ')).join('\n');state.diagnostics=['Import rejected: '+issues.length+' issue(s). See the cell-by-cell report below.'];ui();}
 const markers=Array.from({length:4},()=>{const m=new T.Mesh(new T.TorusGeometry(2.5,.2,4,24),new T.MeshBasicMaterial({color:0xff658b}));m.rotation.x=Math.PI/2;m.visible=false;root.add(m);return m;});
 function ui(){ $('wave-status').textContent=`${state.phase.toUpperCase()} · WAVE ${state.wave} · MAIN ${Math.max(0,Math.ceil(state.hp))}/600 · SCRAP ${state.scrap} · ${pool.filter(e=>e.active).length} shadows\n${state.diagnostics.join(' · ')}`;$('wave-next').disabled=state.phase!=='break'||importing;$('wave-repair').disabled=state.phase!=='break'||state.scrap<20||state.hp>=600;$('wave-start').disabled=$('wave-saved').disabled=preparing||importing;$('build').disabled=preparing||importing||state.phase==='wave'; }
 function clear(){for(const e of pool){e.active=false;e.sprite.visible=false;}}
 async function prepare(starter,fromImport=false){if(preparing||importing&&!fromImport)return;preparing=true;clear();state.phase='checking';state.diagnostics=['Reading actual floors and walls…'];ui();try{
  if(starter){layout=starterLayout();options={level:10,material:'fortress'};builder.construction.apply(0,layout,options);}if(!builder.construction.counts[0].custom)throw new Error('Apply a castle with a MAIN core, or choose Quick starter.');
  onChanged();const design=builder.construction.designs[0];layout=design.layout;options=design.options;scene.updateMatrixWorld(true);await nav.rebuild();routes=await siegeRoutes(world,nav,layout);routes.forEach((r,i)=>{markers[i].position.set(r.start.x,r.start.y+.15,r.start.z);markers[i].visible=true;});
  Object.assign(state,{phase:'break',wave:0,hp:600,scrap:40,kills:0,time:0,routes:routes.map(r=>({sector:labels[r.sector],points:r.points.length})),spawned:0});state.diagnostics=['Four checked approach sectors. Next wave: '+wavePlan(1,state.seed).length+' raiders.'];physics.recover();follow();
  try{localStorage.setItem('crusaders-wave-defense-design-v1',JSON.stringify({format:'crusaders-layout',version:1,layout,options}));}catch{state.diagnostics.push('Design storage unavailable; export to keep a backup.');}
 }catch(e){state.phase='blocked';state.diagnostics=[e.message];markers.forEach(m=>m.visible=false);}finally{preparing=false;ui();}}
 function next(){if(state.phase!=='break'||importing)return;state.wave++;state.phase='wave';state.diagnostics=['Incoming: '+labels.join(' / ')];clock=0;const plan=wavePlan(state.wave,state.seed);for(let i=0;i<plan.length;i++){const e=pool[i],spec=plan[i],route=routes.find(r=>r.sector===spec.sector);Object.assign(e,{...spec,active:true,delay:i*.65,path:route.points,index:1,stuck:0,attack:0});e.sim=e.sim||flightWorld(world.solids,[{...route.points[0],r:2}]);Object.assign(e.sim.state,{...route.points[0],vx:0,vy:0,vz:0,grounded:true,falls:0});e.sprite.visible=false;state.spawned++;}ui();}
 $('wave-start').onclick=()=>prepare(true);$('wave-saved').onclick=()=>prepare(false);$('wave-next').onclick=next;$('wave-repair').onclick=()=>{if(state.phase==='break'&&state.scrap>=20&&state.hp<600){state.scrap-=20;state.hp=Math.min(600,state.hp+150);ui();}};
 $('wave-export').onclick=()=>{const current=builder.construction.designs[0];if(!current){state.diagnostics=['Apply a castle first.'];ui();return;}const d={format:'crusaders-layout',version:1,...current,source:'crusaders-wave-defense'};const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='crusaders-layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 async function importDesign(text){let acquired=false;try{if(state.phase==='wave'||preparing||importing)throw Error('Import between waves only, after the previous check finishes.');importing=true;acquired=true;ui();const d=parseDesign(text);const ingress=approachIssues(d.layout);if(ingress.length)throw new DesignRejection(ingress,'approach');let preview;try{preview=builder.construction.preview(0,d.layout,d.options);if(d.layout.filter(p=>p.type==='core').length!==1)throw Error('Exactly one MAIN core required.');const footprint=inspectCastleFootprint(d.layout);if(!footprint.ok)throw new DesignRejection(physicalIssues(footprint),'footprint');if(preview.links.some(l=>!l.linked))throw Error('Protector beam blocked.');const candidateNav=createBattleNavigation({solids:preview.colliders,castles:[preview.root,new T.Group()],pads:[{x:22,y:.77,z:74,r:2},{x:500,y:.77,z:74,r:2}],routes:[]});try{await candidateNav.rebuild();await siegeRoutes({castles:[preview.root]},candidateNav,d.layout);}finally{candidateNav.dispose();}const result=await inspectCastle(preview,d.layout,d.options);if(!result.ok)throw new DesignRejection(physicalIssues(result),'physical');}finally{preview?.dispose();}builder.construction.apply(0,d.layout,d.options);await prepare(false,true);state.importReport={accepted:state.phase==='break',issues:[],geometryProfile:'wave-pin-20261013',warnings:['Checked with Wave’s pinned core/tower/battery geometry. New Environment mounted armory, rotating cores and weapon behavior are not transferred.']};importFeedback.textContent='Imported design passed the Wave checks using Wave’s pinned geometry. New Environment mounted armory and core appearance/weapon behavior are not transferred.';return state.phase;}catch(error){rejection(error);throw error;}finally{if(acquired)importing=false;ui();}}
 $('wave-import').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>=200000)throw Error('Design must be under 200 KB.');await importDesign(await file.text());}catch(e){rejection(e);}};
 addEventListener('keydown',e=>{if(e.code==='KeyJ'&&!e.target.matches('input,textarea'))held.add(e.code);});addEventListener('keyup',e=>held.delete(e.code));addEventListener('blur',()=>held.clear());
 function tick(dt){const started=performance.now();if(paused()||builder.isOpen){held.clear();return;}if(state.phase!=='wave')return;state.time+=dt;clock+=dt;cooldown=Math.max(0,cooldown-dt);
  for(const e of pool){if(!e.active||clock<e.delay)continue;const s=e.sim.state;e.sprite.visible=true;let remaining=dt;while(remaining>0){const step=Math.min(1/120,remaining);remaining-=step;const target=e.path[e.index],dx=target.x-s.x,dz=target.z-s.z,d=Math.hypot(dx,dz);if(d<.3&&Math.abs(s.y-target.y)<.3){if(e.index<e.path.length-1)e.index++;else{e.attack+=step;if(e.attack>=1){state.hp-=e.damage;e.attack=0;if(state.hp<=0)break;}continue;}}else{const old={x:s.x,z:s.z};e.sim.step(step,{x:dx/(d||1)*e.speed,z:dz/(d||1)*e.speed});e.stuck=Math.hypot(s.x-old.x,s.z-old.z)<.0001?e.stuck+step:0;if(s.falls||e.stuck>3){state.phase='blocked';state.diagnostics=['Route '+labels[e.sector]+' failed during actual movement. Restart after checking this floor/stair.'];clear();break;}}}e.sprite.position.set(s.x,s.y,s.z);}
  if(held.has('KeyJ')&&cooldown===0){const p=physics.state,targets=pool.filter(e=>e.active&&e.sprite.visible&&Math.hypot(e.sim.state.x-p.x,e.sim.state.z-p.z)<26&&Math.abs(e.sim.state.y-p.y)<8&&nav.lineOfSight({...p,y:p.y+1},{...e.sim.state,y:e.sim.state.y+1})).sort((a,b)=>Math.hypot(a.sim.state.x-p.x,a.sim.state.z-p.z)-Math.hypot(b.sim.state.x-p.x,b.sim.state.z-p.z));if(targets[0]){const e=targets[0];e.hp--;e.sprite.material.color.set(e.hp%2?0x865785:0x39204f);if(e.hp<=0){e.active=false;e.sprite.visible=false;state.kills++;state.scrap=Math.min(120,state.scrap+3);}cooldown=.24;}}
  if(state.hp<=0){state.hp=0;state.phase='defeat';state.diagnostics=['MAIN core destroyed. Restart or recover saved castle.'];clear();}else if(state.phase==='wave'&&!pool.some(e=>e.active)){state.phase='break';state.scrap=Math.min(120,state.scrap+15);state.diagnostics=['Wave cleared. Repair, edit, or send the next seeded wave.'];}state.frameMs.push(performance.now()-started);if(state.frameMs.length>600)state.frameMs.shift();ui();
 }
 try{const saved=localStorage.getItem('crusaders-wave-defense-design-v1');if(saved){const d=parseDesign(saved);builder.construction.apply(0,d.layout,d.options);onChanged();state.diagnostics=['Recovered last checked Wave design. Choose Defend current castle.'];}}catch{}
 ui();return {tick,state,prepare,next,pool,nav,importDesign,designChanged(){clear();markers.forEach(m=>m.visible=false);state.phase='ready';state.diagnostics=['Castle edited. Defend current castle to check new routes before starting a fresh run.'];ui();}};
}








